// Omnibox account picker for one Google service (see service.js, generated by build.sh).
//
// Where the account list comes from:
//  1. accounts.google.com/ListAccounts: the endpoint Chrome itself uses to show the
//     Google accounts signed in to the browser's cookie jar. Its order is the
//     /u/N/ index. Fetched every time the keyword is entered, so it is always fresh.
//  2. Memory: content.js reports the account (index + email + name) of every Gmail
//     or Drive page you open, read from the account button in the top-right corner.
//     Used when ListAccounts can't be reached, and to fill in missing names.

import { SERVICE } from "./service.js";

const LIST_ACCOUNTS_URL =
  "https://accounts.google.com/ListAccounts?gpsia=1&source=ChromiumBrowser&json=standard";
const FRESH_MS = 60 * 1000;

let lastFetch = 0;
let refreshing = null;

// ---------- storage ----------

async function loadAccounts() {
  const { accounts = [] } = await chrome.storage.local.get("accounts");
  return accounts.sort((a, b) => a.index - b.index);
}

async function saveAccounts(accounts) {
  await chrome.storage.local.set({ accounts });
}

// ---------- ListAccounts ----------

function parseListAccounts(text) {
  const start = text.indexOf("[");
  if (start < 0) throw new Error("unexpected ListAccounts response");
  const data = JSON.parse(text.slice(start));
  const rows = Array.isArray(data) ? data[1] : null;
  if (!Array.isArray(rows)) throw new Error("unexpected ListAccounts shape");
  const out = [];
  for (const row of rows) {
    if (!Array.isArray(row) || typeof row[3] !== "string") continue;
    const signedOut = row.length > 14 && row[14] === 1;
    if (signedOut) continue; // still listed by Google, but has no /u/N/ session
    out.push({
      index: out.length,
      email: row[3],
      name: typeof row[2] === "string" ? row[2] : "",
      photo: typeof row[4] === "string" ? row[4] : "",
    });
  }
  return out;
}

async function fetchListAccounts() {
  for (const method of ["GET", "POST"]) {
    try {
      const res = await fetch(LIST_ACCOUNTS_URL, { method, credentials: "include" });
      if (!res.ok) continue;
      return parseListAccounts(await res.text());
    } catch (e) {
      console.warn("ListAccounts", method, e);
    }
  }
  return null;
}

function refresh(force = false) {
  if (!force && Date.now() - lastFetch < FRESH_MS) return Promise.resolve();
  if (refreshing) return refreshing;
  refreshing = (async () => {
    const live = await fetchListAccounts();
    if (live) {
      const known = new Map((await loadAccounts()).map((a) => [a.email, a]));
      for (const a of live) {
        if (!a.name && known.get(a.email)?.name) a.name = known.get(a.email).name;
        a.source = "live";
      }
      // Google's list is authoritative: accounts that disappeared were signed out.
      await saveAccounts(live);
    }
    lastFetch = Date.now(); // also after a failure: don't retry on every keystroke
  })().finally(() => (refreshing = null));
  return refreshing;
}

// ---------- reports from content.js ----------

chrome.runtime.onMessage.addListener((msg) => {
  if (msg?.type !== "account-seen") return;
  (async () => {
    const { email, name, index } = msg;
    let accounts = await loadAccounts();
    // Another email at the same index means the indexes shifted: drop the stale one.
    accounts = accounts.filter((a) => a.email === email || a.index !== index);
    const existing = accounts.find((a) => a.email === email);
    if (existing) {
      existing.index = index;
      if (name) existing.name = name;
    } else {
      accounts.push({ index, email, name: name || "", source: "seen" });
    }
    await saveAccounts(accounts);
  })();
});

// ---------- omnibox ----------

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" })[c]);
}

function urlFor(account) {
  return SERVICE.url.replace("{index}", account.index);
}

function matches(accounts, text) {
  const q = text.trim().toLowerCase();
  if (!q) return accounts;
  if (/^\d+$/.test(q)) {
    const byIndex = accounts.filter((a) => String(a.index) === q);
    if (byIndex.length) return byIndex;
  }
  const words = q.split(/\s+/);
  return accounts.filter((a) => {
    const hay = `${a.name} ${a.email}`.toLowerCase();
    return words.every((w) => hay.includes(w));
  });
}

function describe(a) {
  const name = a.name ? `<match>${esc(a.name)}</match> ` : "";
  return `${name}<dim>${esc(a.email)}</dim> <url>/u/${a.index}/</url>`;
}

chrome.omnibox.setDefaultSuggestion({ description: `Open ${SERVICE.label}: type a name, email or number` });

chrome.omnibox.onInputStarted.addListener(() => {
  refresh(true);
});

chrome.omnibox.onInputChanged.addListener(async (text, suggest) => {
  await refresh();
  const accounts = await loadAccounts();
  const found = matches(accounts, text);
  if (!accounts.length) {
    chrome.omnibox.setDefaultSuggestion({
      description: `No Google accounts known yet: open ${esc(SERVICE.label)} once in each account`,
    });
    suggest([]);
    return;
  }
  if (!found.length) {
    chrome.omnibox.setDefaultSuggestion({ description: `No account matches <match>${esc(text)}</match>` });
    suggest([]);
    return;
  }
  // Enter without choosing opens the first match; the rest are listed below it.
  chrome.omnibox.setDefaultSuggestion({ description: `${esc(SERVICE.label)}: ${describe(found[0])}` });
  suggest(found.slice(1).map((a) => ({ content: urlFor(a), description: describe(a) })));
});

chrome.omnibox.onInputEntered.addListener(async (text, disposition) => {
  let url;
  if (/^https:\/\//.test(text)) {
    url = text; // a suggestion was chosen
  } else {
    const found = matches(await loadAccounts(), text);
    if (found.length) url = urlFor(found[0]);
    else if (text.includes("@")) url = SERVICE.emailUrl.replace("{email}", encodeURIComponent(text.trim()));
    else url = SERVICE.url.replace("{index}", "0");
  }
  if (disposition === "currentTab") chrome.tabs.update({ url });
  else chrome.tabs.create({ url, active: disposition === "newForegroundTab" });
});
